% =========================================================================
% 專題名稱：車內乘客呼吸心跳偵測 (Phase 3: 車體震動干擾與 DSP 濾波)
% =========================================================================

% 1. 基本雷達參數與時間軸設定 (與 Phase 2 相同)
fc = 60e9; bw = 4e9; sweepTime = 1e-3; fs = 2 * bw; c = 3e8; slope = bw / sweepTime;
fps = 100; duration = 10; numChirps = fps * duration; 
timeVec = (0:numChirps-1) / fps;

% 2. 物理微動模型：加入「車體震動」雜訊
Ar = 0.005;  fr = 0.3; % 呼吸 (5mm, 0.3Hz)
Ah = 0.0005; fh = 1.2; % 心跳 (0.5mm, 1.2Hz)

% 【新增】模擬車輛怠速或行進間的震動 (低頻晃動 20mm + 隨機高頻白雜訊)
car_sway = 0.02 * sin(2 * pi * 0.1 * timeVec); 
random_noise = 0.0005 * randn(1, numChirps);

% 總位移 = 呼吸 + 心跳 + 車體晃動 + 隨機雜訊
displacement = Ar*sin(2*pi*fr*timeVec) + Ah*sin(2*pi*fh*timeVec) + car_sway + random_noise;

% 3. 快速模擬雷達相位解包 (為節省運算時間，直接透過物理公式產生含雜訊的相位)
% 真實情況下這裡會跑 dechirp 和 FFT，這裡我們直接拿萃取出的相位來處理
lambda = c / fc;
noisy_phase = (4 * pi * displacement) / lambda; 
noisy_phase = noisy_phase - mean(noisy_phase); % 移除直流偏移

% 4. 數位訊號處理 (DSP)：頻帶濾波器 (Bandpass Filter)
% 利用濾波器將混合在一起的訊號「過濾」開來
% 呼吸頻段通常在 0.15 Hz ~ 0.5 Hz (每分鐘 9~30 次)
filtered_breathing = bandpass(noisy_phase, [0.15 0.5], fps);

% 心跳頻段通常在 0.8 Hz ~ 2.0 Hz (每分鐘 48~120 次)
filtered_heartbeat = bandpass(noisy_phase, [0.8 2.0], fps);

% 5. 繪製濾波前後的對比圖
figure('Position', [100, 100, 800, 600]); %[output:77bee7c2]

% 原始含雜訊的相位 (你根本看不出心跳)
subplot(3,1,1); %[output:77bee7c2]
plot(timeVec, noisy_phase, 'Color', [0.5 0.5 0.5], 'LineWidth', 1); %[output:77bee7c2]
title('Raw Extracted Phase (Corrupted by Vehicle Vibration & Noise)'); %[output:77bee7c2]
ylabel('Phase (rad)'); grid on; %[output:77bee7c2]

% 濾波後的呼吸訊號
subplot(3,1,2); %[output:77bee7c2]
plot(timeVec, filtered_breathing, 'b', 'LineWidth', 1.5); %[output:77bee7c2]
title('Recovered Breathing Signal (Bandpass: 0.15 - 0.5 Hz)'); %[output:77bee7c2]
ylabel('Phase (rad)'); grid on; %[output:77bee7c2]

% 濾波後的心跳訊號
subplot(3,1,3); %[output:77bee7c2]
plot(timeVec, filtered_heartbeat, 'r', 'LineWidth', 1.5); %[output:77bee7c2]
title('Recovered Heartbeat Signal (Bandpass: 0.8 - 2.0 Hz)'); %[output:77bee7c2]
xlabel('Time (s)'); ylabel('Phase (rad)'); grid on; %[output:77bee7c2]

